//! JSON benchmark at session scale: serde_json vs sonic-rs vs simd-json.
//!   cargo run -q --release -p smash-ext --example json-bench
//!
//! Payload is a realistic session transcript: messages with text, thinking and
//! tool-call parts, dominated by strings.

use std::time::Instant;

use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Serialize, Deserialize)]
struct Msg {
    id: u64,
    role: String,
    content: Vec<Part>,
}

#[derive(Serialize, Deserialize)]
enum Part {
    Text { text: String },
    Thinking { text: String },
    ToolCall { name: String, arguments: Value },
}

fn session(messages: usize) -> Vec<Msg> {
    let body =
        "lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor ".repeat(6);
    (0..messages as u64)
        .map(|id| Msg {
            id,
            role: if id % 2 == 0 {
                "user".into()
            } else {
                "assistant".into()
            },
            content: vec![
                Part::Text {
                    text: format!("{body}/{id}"),
                },
                Part::Thinking {
                    text: format!("thinking about {id}: {body}"),
                },
                Part::ToolCall {
                    name: "read_file".into(),
                    arguments: serde_json::json!({ "path": format!("/tmp/{id}") }),
                },
            ],
        })
        .collect()
}

